def memory_create_entities(entities, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    allowed_types = {"event", "location", "organization", "paper", "person", "project", "technology", "university"}

    if not isinstance(entities, list) or len(entities) == 0:
        return _err("VALIDATION_ERROR", "entities must be a non-empty array")

    seen_names = set()
    for i, e in enumerate(entities):
        if not isinstance(e, dict):
            return _err("VALIDATION_ERROR", "each entity must be an object", index=i)
        if "name" not in e or "entityType" not in e or "observations" not in e:
            return _err("VALIDATION_ERROR", "each entity must include name, entityType, and observations", index=i)
        if not isinstance(e["name"], str) or not e["name"].strip():
            return _err("VALIDATION_ERROR", "entity.name must be a non-empty string", index=i)
        if not isinstance(e["entityType"], str) or e["entityType"] not in allowed_types:
            return _err("VALIDATION_ERROR", "entity.entityType must be one of the allowed enum values", index=i, allowed=sorted(allowed_types))
        if not isinstance(e["observations"], list) or any(not isinstance(o, str) for o in e["observations"]):
            return _err("VALIDATION_ERROR", "entity.observations must be an array of strings", index=i)
        nm = e["name"].strip()
        if nm in seen_names:
            return _err("CONFLICT", "duplicate entity name in request", name=nm)
        seen_names.add(nm)

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    existing = {e.get("name") for e in g["entities"] if isinstance(e, dict)}
    conflicts = [nm for nm in seen_names if nm in existing]
    if conflicts:
        return _err("CONFLICT", "one or more entity names already exist", conflicts=sorted(conflicts))

    created = []
    for e in entities:
        row = {
            "name": e["name"].strip(),
            "entityType": e["entityType"],
            "observations": list(e["observations"]),
        }
        g["entities"].append(row)
        created.append(row)

    _save("memory_graph.json", g)
    return {"entities": created, "created_count": len(created)}

def memory_create_relations(relations, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
