            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(relations, list) or len(relations) == 0:
        return _err("VALIDATION_ERROR", "relations must be a non-empty array")

    for i, r in enumerate(relations):
        if not isinstance(r, dict):
            return _err("VALIDATION_ERROR", "each relation must be an object", index=i)
        if "from" not in r or "to" not in r or "relationType" not in r:
            return _err("VALIDATION_ERROR", "each relation must include from, to, and relationType", index=i)
        if not isinstance(r["from"], str) or not r["from"].strip():
            return _err("VALIDATION_ERROR", "relation.from must be a non-empty string", index=i)
        if not isinstance(r["to"], str) or not r["to"].strip():
            return _err("VALIDATION_ERROR", "relation.to must be a non-empty string", index=i)
        if not isinstance(r["relationType"], str) or not r["relationType"].strip():
            return _err("VALIDATION_ERROR", "relation.relationType must be a non-empty string", index=i)

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    entity_names = {e.get("name") for e in g["entities"] if isinstance(e, dict)}
    unknown = []
    for r in relations:
        f = r["from"].strip()
        t = r["to"].strip()
        if f not in entity_names:
            unknown.append(f)
        if t not in entity_names:
            unknown.append(t)
    if unknown:
        return _err("NOT_FOUND", "one or more referenced entities do not exist", unknown_entities=sorted(set(unknown)))

    existing = set()
    for rr in g["relations"]:
        if isinstance(rr, dict):
            existing.add((rr.get("from"), rr.get("to"), rr.get("relationType")))

    req_keys = []
    dup_in_request = set()
    for r in relations:
        key = (r["from"].strip(), r["to"].strip(), r["relationType"].strip())
        if key in req_keys:
            dup_in_request.add(key)
        req_keys.append(key)
    if dup_in_request:
        return _err("CONFLICT", "duplicate relations in request", duplicates=[{"from": k[0], "to": k[1], "relationType": k[2]} for k in sorted(dup_in_request)])

    conflicts = [k for k in req_keys if k in existing]
    if conflicts:
        return _err("CONFLICT", "one or more relations already exist", conflicts=[{"from": k[0], "to": k[1], "relationType": k[2]} for k in conflicts])

    created = []
    for k in req_keys:
        row = {"from": k[0], "to": k[1], "relationType": k[2]}
        g["relations"].append(row)
        created.append(row)

    _save("memory_graph.json", g)
    return {"relations": created, "created_count": len(created)}

def memory_add_observations(observations, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(observations, list) or len(observations) == 0:
        return _err("VALIDATION_ERROR", "observations must be a non-empty array")

    for i, o in enumerate(observations):
        if not isinstance(o, dict):
            return _err("VALIDATION_ERROR", "each observation item must be an object", index=i)
        if "entityName" not in o or "contents" not in o:
            return _err("VALIDATION_ERROR", "each observation item must include entityName and contents", index=i)
        if not isinstance(o["entityName"], str) or not o["entityName"].strip():
            return _err("VALIDATION_ERROR", "entityName must be a non-empty string", index=i)
        if not isinstance(o["contents"], list) or len(o["contents"]) == 0 or any(not isinstance(s, str) for s in o["contents"]):
            return _err("VALIDATION_ERROR", "contents must be a non-empty array of strings", index=i)

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    idx = {}
    for e in g["entities"]:
        if isinstance(e, dict) and isinstance(e.get("name"), str):
            idx[e["name"]] = e

    unknown = []
    for o in observations:
        nm = o["entityName"].strip()
        if nm not in idx:
            unknown.append(nm)
    if unknown:
        return _err("NOT_FOUND", "one or more entities do not exist", unknown_entities=sorted(set(unknown)))

    updated_entities = []
    updated_set = set()
    total_added = 0
    for o in observations:
        nm = o["entityName"].strip()
        ent = idx[nm]
        if "observations" not in ent or not isinstance(ent.get("observations"), list):
            ent["observations"] = []
        before = len(ent["observations"])
        ent["observations"].extend(list(o["contents"]))
        added = len(ent["observations"]) - before
        total_added += added
        if nm not in updated_set:
            updated_entities.append(ent)
            updated_set.add(nm)

    if total_added == 0:
        return _err("NOT_FOUND", "no observations were added")

    _save("memory_graph.json", g)
    return {"entities": updated_entities, "added_count": total_added}

def memory_delete_entities(entityNames, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(entityNames, list) or len(entityNames) == 0:
        return _err("VALIDATION_ERROR", "entityNames must be a non-empty array")
    if any(not isinstance(n, str) or not n.strip() for n in entityNames):
        return _err("VALIDATION_ERROR", "entityNames must contain only non-empty strings")

    to_delete = [n.strip() for n in entityNames]
    if len(set(to_delete)) != len(to_delete):
        return _err("VALIDATION_ERROR", "entityNames must not contain duplicates")

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    existing = {e.get("name") for e in g["entities"] if isinstance(e, dict)}
    missing = [n for n in to_delete if n not in existing]
    if missing:
        return _err("NOT_FOUND", "one or more entities do not exist", missing=missing)

    delset = set(to_delete)
    deleted_entities = [e for e in g["entities"] if isinstance(e, dict) and e.get("name") in delset]
    kept_entities = [e for e in g["entities"] if not (isinstance(e, dict) and e.get("name") in delset)]

    deleted_relations = []
    kept_relations = []
    for r in g["relations"]:
        if isinstance(r, dict) and (r.get("from") in delset or r.get("to") in delset):
            deleted_relations.append(r)
        else:
            kept_relations.append(r)

    if len(deleted_entities) == 0:
        return _err("NOT_FOUND", "no entities deleted")

    g["entities"] = kept_entities
    g["relations"] = kept_relations
    _save("memory_graph.json", g)
    return {
        "deleted_entities": deleted_entities,
        "deleted_relations": deleted_relations,
        "deleted_entity_count": len(deleted_entities),
        "deleted_relation_count": len(deleted_relations),
    }

def memory_delete_observations(deletions, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(deletions, list) or len(deletions) == 0:
        return _err("VALIDATION_ERROR", "deletions must be a non-empty array")

    for i, d in enumerate(deletions):
        if not isinstance(d, dict):
            return _err("VALIDATION_ERROR", "each deletion item must be an object", index=i)
        if "entityName" not in d or "observations" not in d:
            return _err("VALIDATION_ERROR", "each deletion item must include entityName and observations", index=i)
        if not isinstance(d["entityName"], str) or not d["entityName"].strip():
            return _err("VALIDATION_ERROR", "entityName must be a non-empty string", index=i)
        if not isinstance(d["observations"], list) or len(d["observations"]) == 0 or any(not isinstance(s, str) for s in d["observations"]):
            return _err("VALIDATION_ERROR", "observations must be a non-empty array of strings", index=i)

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    idx = {}
    for e in g["entities"]:
        if isinstance(e, dict) and isinstance(e.get("name"), str):
            idx[e["name"]] = e

    unknown = []
    for d in deletions:
        nm = d["entityName"].strip()
        if nm not in idx:
            unknown.append(nm)
    if unknown:
        return _err("NOT_FOUND", "one or more entities do not exist", unknown_entities=sorted(set(unknown)))

    removed_total = 0
    removed_by_entity = []
    for d in deletions:
        nm = d["entityName"].strip()
        ent = idx[nm]
        if "observations" not in ent or not isinstance(ent.get("observations"), list):
            ent["observations"] = []

        to_remove = list(d["observations"])
        current = ent["observations"]
        missing_obs = [x for x in to_remove if x not in current]
        if missing_obs:
            return _err("NOT_FOUND", "one or more observations to delete were not found on the entity", entityName=nm, missing_observations=missing_obs)

        remove_set = set(to_remove)
        before = len(current)
        ent["observations"] = [x for x in current if x not in remove_set]
        removed = before - len(ent["observations"])
        removed_total += removed
        removed_by_entity.append({"entityName": nm, "removed": to_remove, "removed_count": removed})

    if removed_total == 0:
        return _err("NOT_FOUND", "no observations deleted")

    _save("memory_graph.json", g)
    return {"removed": removed_by_entity, "removed_count": removed_total}

def memory_delete_relations(relations, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(relations, list) or len(relations) == 0:
        return _err("VALIDATION_ERROR", "relations must be a non-empty array")

    for i, r in enumerate(relations):
        if not isinstance(r, dict):
            return _err("VALIDATION_ERROR", "each relation must be an object", index=i)
        if "from" not in r or "to" not in r or "relationType" not in r:
            return _err("VALIDATION_ERROR", "each relation must include from, to, and relationType", index=i)
        if not isinstance(r["from"], str) or not r["from"].strip():
            return _err("VALIDATION_ERROR", "relation.from must be a non-empty string", index=i)
        if not isinstance(r["to"], str) or not r["to"].strip():
            return _err("VALIDATION_ERROR", "relation.to must be a non-empty string", index=i)
        if not isinstance(r["relationType"], str) or not r["relationType"].strip():
            return _err("VALIDATION_ERROR", "relation.relationType must be a non-empty string", index=i)

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        g = {}
    if "entities" not in g or not isinstance(g.get("entities"), list):
        g["entities"] = []
    if "relations" not in g or not isinstance(g.get("relations"), list):
        g["relations"] = []

    entity_names = {e.get("name") for e in g["entities"] if isinstance(e, dict)}
    unknown = []
    keys = []
    for r in relations:
        f = r["from"].strip()
        t = r["to"].strip()
        rt = r["relationType"].strip()
        if f not in entity_names:
            unknown.append(f)
        if t not in entity_names:
            unknown.append(t)
        keys.append((f, t, rt))
    if unknown:
        return _err("NOT_FOUND", "one or more referenced entities do not exist", unknown_entities=sorted(set(unknown)))

    existing = set()
    for rr in g["relations"]:
        if isinstance(rr, dict):
            existing.add((rr.get("from"), rr.get("to"), rr.get("relationType")))

    missing_rel = [k for k in keys if k not in existing]
    if missing_rel:
        return _err(
            "NOT_FOUND",
            "one or more relations do not exist",
            missing=[{"from": k[0], "to": k[1], "relationType": k[2]} for k in missing_rel],
        )

    keyset = set(keys)
    deleted = []
    kept = []
    for rr in g["relations"]:
        if not isinstance(rr, dict):
            kept.append(rr)
            continue
        k = (rr.get("from"), rr.get("to"), rr.get("relationType"))
        if k in keyset:
            deleted.append(rr)
        else:
            kept.append(rr)

    if len(deleted) == 0:
        return _err("NOT_FOUND", "no relations deleted")

    g["relations"] = kept
    _save("memory_graph.json", g)
    return {"deleted_relations": deleted, "deleted_count": len(deleted)}

