def memory_search_nodes(query, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if not q:
        return _err("VALIDATION_ERROR", "query must not be empty")
    ql = q.lower()

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        return {"entities": [], "relations": [], "total_entities": 0}

    entities = g.get("entities") if isinstance(g.get("entities"), list) else []
    relations = g.get("relations") if isinstance(g.get("relations"), list) else []

    matched = []
    for e in entities:
        if not isinstance(e, dict):
            continue
        name = e.get("name") if isinstance(e.get("name"), str) else ""
        et = e.get("entityType") if isinstance(e.get("entityType"), str) else ""
        obs = e.get("observations") if isinstance(e.get("observations"), list) else []
        obs_strs = [o for o in obs if isinstance(o, str)]
        if (ql in name.lower()) or (ql in et.lower()) or any(ql in o.lower() for o in obs_strs):
            matched.append(e)

    names = {e.get("name") for e in matched if isinstance(e, dict)}
    matched_rel = []
    for r in relations:
        if not isinstance(r, dict):
            continue
        if r.get("from") in names and r.get("to") in names:
            matched_rel.append(r)

    return {"entities": matched, "relations": matched_rel, "total_entities": len(matched)}

def memory_open_nodes(names, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0206000" if __import__("os").path.isdir("./environment_mix/0206000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(names, list) or len(names) == 0:
        return _err("VALIDATION_ERROR", "names must be a non-empty array")
    if any(not isinstance(n, str) or not n.strip() for n in names):
        return _err("VALIDATION_ERROR", "names must contain only non-empty strings")

    want = [n.strip() for n in names]
    if len(set(want)) != len(want):
        return _err("VALIDATION_ERROR", "names must not contain duplicates")

    g = _load("memory_graph.json")
    if not isinstance(g, dict):
        return _err("NOT_FOUND", "one or more entities do not exist", missing=want)

    entities = g.get("entities") if isinstance(g.get("entities"), list) else []
    relations = g.get("relations") if isinstance(g.get("relations"), list) else []

    idx = {e.get("name"): e for e in entities if isinstance(e, dict) and isinstance(e.get("name"), str)}
    missing = [n for n in want if n not in idx]
    if missing:
        return _err("NOT_FOUND", "one or more entities do not exist", missing=missing)

    ents = [idx[n] for n in want]
    wantset = set(want)
    rels = [r for r in relations if isinstance(r, dict) and r.get("from") in wantset and r.get("to") in wantset]
    return {"entities": ents, "relations": rels, "entity_count": len(ents), "relation_count": len(rels)}
